export type DetailState =
  | { kind: "loading" }
  | { kind: "member"; details: MemberDetails }
  | { kind: "funder"; details: FunderDetails }
  | { kind: "not-found" }
  | { kind: "error"; message: string };

export function backToSearch(params: Pick<URLSearchParams, "get">): string {
  const retained = new URLSearchParams();
  for (const key of ["q", "strictness"]) {
    const value = params.get(key);
    if (value !== null) retained.set(key, value);
  }
  return retained.size ? `/?${retained}` : "/";
}

export function formatAmount(value: string | null): string {
  if (value === null) return "Amount unavailable";
  const negative = value.startsWith("-");
  const unsigned = negative ? value.slice(1) : value;
  const [whole, fraction] = unsigned.split(".");
  return `${negative ? "−" : ""}${whole.replace(/\B(?=(\d{3})+(?!\d))/gu, ",")}${fraction === undefined ? "" : `.${fraction}`}`;
}

export function registrationDate(value: string): string {
  return new Intl.DateTimeFormat("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
    timeZone: "UTC",
  }).format(new Date(value));
}

export function memberHref(
  id: string,
  view: "summary" | "history",
  params: Pick<URLSearchParams, "get">,
): string {
  const search = backToSearch(params).slice(1);
  return `/members/${id}${view === "history" ? "/history" : ""}${search}`;
}

export function categoryBars(
  categories: { amount: string | null }[],
  basis: "total" | "maximum",
): { width: number; negative: boolean }[] {
  const scale = Math.max(
    0,
    ...categories.map(({ amount }) => amount?.split(".")[1]?.length ?? 0),
  );
  const values = categories.map(({ amount }) => {
    if (amount === null) return 0n;
    const [whole, fraction = ""] = amount.replace(/^-/, "").split(".");
    const value = BigInt(whole + fraction.padEnd(scale, "0"));
    return amount.startsWith("-") ? -value : value;
  });
  const magnitudes = values.map((value) => (value < 0n ? -value : value));
  let denominator: bigint;
  let precision: bigint;
  switch (basis) {
    case "total":
      denominator = magnitudes.reduce((total, value) => total + value, 0n);
      precision = 100000000n;
      break;
    case "maximum":
      denominator = magnitudes.reduce(
        (largest, value) => (value > largest ? value : largest),
        0n,
      );
      precision = 100n;
      break;
    default: {
      const exhaustive: never = basis;
      return exhaustive;
    }
  }
  return values.map((value, index) => ({
    negative: value < 0n,
    width:
      denominator === 0n
        ? 0
        : Number((magnitudes[index] * 100n * precision) / denominator) /
          Number(precision),
  }));
}

export function funderHref(
  id: string,
  view: "summary" | "history",
  params: Pick<URLSearchParams, "get">,
): string {
  const search = backToSearch(params).slice(1);
  return `/funders/${id}${view === "history" ? "/history" : ""}${search}`;
}
<script lang="ts">
  import Icon from "./lib/Icon.svelte";
  import EntityIndicator from "./lib/EntityIndicator.svelte";
  import {
    entityHref,
    highlightName,
    readStrictness,
    searchConfiguration,
    type Entity,
  } from "./lib/search";

  import { onMount, untrack } from "svelte";
  import { page } from "$app/state";
  import { goto, afterNavigate } from "$app/navigation";
  import type { PageModel, SearchResult } from "./lib/page";
  let { model }: { model: Extract<PageModel, { kind: "search" }> } = $props();
  type SearchState = SearchResult | { status: "loading"; term: string };
  type SearchFocusShortcut =
    { modifier: "meta"; hint: "⌘ K" } | { modifier: "ctrl"; hint: "Ctrl K" };
  let searchFocusShortcut = $state<SearchFocusShortcut>({
    modifier: "ctrl",
    hint: "Ctrl K",
  });
  onMount(() => {
    if (/Mac/i.test(navigator.platform))
      searchFocusShortcut = { modifier: "meta", hint: "⌘ K" };
  });
  let query = $state(untrack(() => model.query));
  let strictness = $state(untrack(() => model.strictness));
  afterNavigate(({ type }) => {
    if (type === "popstate" || type === "link") {
      query = page.url.searchParams.get("q") ?? "";
      strictness = readStrictness(page.url.searchParams.get("strictness"));
    }
  });
  let composing = $state(false);
  let attempt = $state(0);
  let input: HTMLInputElement;
  let pending = $state(false);
  const term = $derived(query.trim());
  const charactersNeeded = $derived(
    Math.max(0, searchConfiguration.minimumCharacters - [...term].length),
  );
  const searchState = $derived<SearchState>(
    composing || charactersNeeded
      ? { status: "idle" }
      : pending ||
          model.query.trim() !== term ||
          model.strictness !== strictness
        ? { status: "loading", term }
        : model.result,
  );
  const announcement = $derived(
    searchState.status === "loading"
      ? "Searching…"
      : searchState.status === "success"
        ? `${searchState.entities.length} ${searchState.entities.length === 1 ? "result" : "results"} shown for ${searchState.term}.`
        : "",
  );

  $effect(() => {
    const currentTerm = term;
    const currentStrictness = strictness;
    const currentAttempt = attempt;
    if (
      composing ||
      [...currentTerm].length < searchConfiguration.minimumCharacters
    )
      return;
    if (
      !currentAttempt &&
      untrack(
        () =>
          model.query.trim() === currentTerm &&
          model.strictness === currentStrictness,
      )
    )
      return;
    let current = true;
    const timer = setTimeout(
      async () => {
        const url = new URL(window.location.href);
        url.searchParams.set("q", currentTerm);
        url.searchParams.set("strictness", String(currentStrictness));
        pending = true;
        try {
          await goto(url, { replace: true, reset: false, refreshAll: true });
        } finally {
          if (current) pending = false;
        }
      },
      currentAttempt ? 0 : searchConfiguration.debounceMs,
    );
    return () => {
      current = false;
      pending = false;
      clearTimeout(timer);
    };
  });

  function updateQuery(value: string) {
    attempt = 0;
    query = value;
    const url = new URL(window.location.href);
    if (value.trim()) url.searchParams.set("q", value.trim());
    else url.searchParams.delete("q");
    void goto(url, {
      shallow: true,
      replace: true,
      reset: false,
      state: page.state,
    });
  }

  function updateStrictness(value: string) {
    attempt = 0;
    strictness = readStrictness(value);
    const url = new URL(window.location.href);
    url.searchParams.set("strictness", String(strictness));
    void goto(url, {
      shallow: true,
      replace: true,
      reset: false,
      state: page.state,
    });
  }

  function clearSearch() {
    updateQuery("");
    input.focus();
  }

  function shortcut(event: KeyboardEvent) {
    if (
      event.key.toLowerCase() === "k" &&
      !event.defaultPrevented &&
      !event.isComposing &&
      !composing &&
      !event.shiftKey &&
      !event.altKey &&
      (searchFocusShortcut.modifier === "meta"
        ? event.metaKey && !event.ctrlKey
        : event.ctrlKey && !event.metaKey)
    ) {
      event.preventDefault();
      input.focus();
      return;
    }
    const target = event.target;
    const editing =
      target instanceof HTMLElement &&
      (target.isContentEditable ||
        ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName));
    if (
      event.key === "/" &&
      !editing &&
      !event.ctrlKey &&
      !event.metaKey &&
      !event.altKey
    ) {
      event.preventDefault();
      input.focus();
    }
    if (event.key === "Escape" && target === input && !event.isComposing)
      clearSearch();
  }

  function atLimit(entities: Entity[]) {
    return ["MP", "Funder"].some(
      (kind) =>
        entities.filter((entity) => entity.kind === kind).length >=
        searchConfiguration.maxEntriesPerType,
    );
  }
</script>

<svelte:window onkeydown={shortcut} />

<main id="search">
